using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _gateway = new PaymentGateway();
    }

    // ── ChargeAsync ──────────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidCard_ReturnsSuccessWithChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 50.00m);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCard_ReturnsNonEmptyChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 100.00m);

        Assert.IsTrue(result.Success);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(1.00)]
    [DataRow(9999.99)]
    public async Task ChargeAsync_VariousValidAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("tok_valid_visa", 0m));
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("tok_valid_visa", -10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ChargeAsync(null!, 25.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(string.Empty, 25.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_declined", 50.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_TwoCharges_ReturnDistinctChargeIds()
    {
        var first = await _gateway.ChargeAsync("tok_valid_visa", 10.00m);
        var second = await _gateway.ChargeAsync("tok_valid_visa", 20.00m);

        Assert.AreNotEqual(first.ChargeId, second.ChargeId);
    }

    // ── RefundAsync ──────────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 75.00m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsNonEmptyRefundId()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 30.00m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.AreNotEqual(string.Empty, refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(string.Empty));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
    {
        var refund = await _gateway.RefundAsync("ch_nonexistent");

        Assert.IsFalse(refund.Success);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ReturnsFailure()
    {
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 40.00m);
        await _gateway.RefundAsync(charge.ChargeId);

        var duplicate = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsFalse(duplicate.Success);
    }

    // ── Record equality ──────────────────────────────────────────────

    [TestMethod]
    public void ChargeResult_EqualValues_AreEqual()
    {
        var a = new ChargeResult("ch_123", true);
        var b = new ChargeResult("ch_123", true);

        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void ChargeResult_DifferentIds_AreNotEqual()
    {
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_2", true);

        Assert.AreNotEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_EqualValues_AreEqual()
    {
        var a = new RefundResult("re_456", true);
        var b = new RefundResult("re_456", true);

        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_DifferentSuccessFlags_AreNotEqual()
    {
        var a = new RefundResult("re_1", true);
        var b = new RefundResult("re_1", false);

        Assert.AreNotEqual(a, b);
    }
}

